window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e4a0da848bad065"]={"versions": [{"id": "FIG-9e4a0da848bad065", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm EcuM Main State Machine</code>). Es stellt die oberste Ebene des Lebenszyklus und der Betriebsmodi des AUTOSAR ECU State Manager (EcuM Fixed) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pseudozustände</strong>:</li>\n<li>Anfangszustand (ausgefüllter Kreis, beschriftet mit <code>OFF</code>).</li>\n<li>Endzustand (umrandeter Kreis mit Punkt, beschriftet mit <code>OFF</code>).</li>\n<li><strong>Zustände (Composite States mit Sub-State-Symbol <code>oo</code>)</strong>:</li>\n<li><code>STARTUP</code></li>\n<li><code>RUN</code></li>\n<li><code>SHUTDOWN</code></li>\n<li><code>SLEEP</code></li>\n<li><code>WAKEUP</code></li>\n<li><strong>Ereignisse / Guards / Aktionen an Übergängen</strong>:</li>\n<li>Ereignisse: <code>Power on</code>, <code>Normal startup</code>, <code>Wakeup by wakeup source with integrated power control</code>, <code>All applications have shut down</code>, <code>Wakeup event</code>, <code>Reset</code>, <code>Power off</code>, <code>other</code>.</li>\n<li>Guard / Action: <code>[SLEEP == true ? /TTII]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Start</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beginn im Pseudozustand <code>OFF</code> über Übergang <code>Power on</code> nach <code>STARTUP</code>.</li>\n<li>Von <code>STARTUP</code> regulärer Wechsel nach <code>RUN</code> über <code>Normal startup</code>.</li>\n<li>Alternativ von <code>STARTUP</code> direkter Wechsel nach <code>WAKEUP</code> über <code>Wakeup by wakeup source with integrated power control</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb und Herunterfahren</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>RUN</code> Übergang nach <code>SHUTDOWN</code>, sobald <code>All applications have shut down</code> eintritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi und Wakeup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> Wechsel nach <code>SLEEP</code> über Bedingung/Ereignis <code>other</code>.</li>\n<li>Bei Auftreten eines Wakeup-Ereignisses (<code>Wakeup event</code>) in <code>SLEEP</code> erfolgt der Übergang nach <code>WAKEUP</code>.</li>\n<li>Tritt bereits während <code>SHUTDOWN</code> ein <code>Wakeup event</code> auf, wird direkt nach <code>WAKEUP</code> gewechselt.</li>\n<li>Ein Übergang führt von <code>WAKEUP</code> zurück nach <code>SHUTDOWN</code> unter der Guard-/Aktionsbedingung <code>SLEEP == true ? /TTII</code>.</li>\n<li>Von <code>WAKEUP</code> führt der reguläre Rückweg über <code>other</code> zurück nach <code>RUN</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung / Neustart</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> über <code>Reset</code> zurück zu <code>STARTUP</code>.</li>\n<li>Von <code>SHUTDOWN</code> über <code>Power off</code> in den Endzustand <code>OFF</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Top-Level-Zustandsverhalten des EcuM (Fixed Architecture).</li>\n<li>Sämtliche Hauptzustände (<code>STARTUP</code>, <code>RUN</code>, <code>SHUTDOWN</code>, <code>SLEEP</code>, <code>WAKEUP</code>) sind hierarchische Verbundzustände mit unterlagerten Zustandsmaschinen.</li>\n<li>Implementierungen müssen sicherstellen, dass Wakeup-Ereignisse sowohl im Ruhezustand (<code>SLEEP</code>) als auch im Herunterfahrprozess (<code>SHUTDOWN</code>) priorisiert abgefangen werden.</li>\n<li>Der Guard <code>SLEEP == true ? /TTII</code> spezifiziert die Rückführung in den Shutdown-Ablauf, falls ein Schlafzustand bereits als Zielbedingung aktiv war bzw. TTII (Time Triggered / Timer Interrupt Handling) greift.</li>\n</ul>"}, {"id": "FIG-2ab6e57d2b5bee8c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Darstellung der obersten Ebene des Lebenszyklus und der Betriebsmodi des AUTOSAR ECU State Manager (EcuM Fixed).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pseudozustände</strong>:</li>\n<li>Anfangszustand (ausgefüllter Kreis, beschriftet mit <code>OFF</code>).</li>\n<li>Endzustand (umrandeter Kreis mit Punkt, beschriftet mit <code>OFF</code>).</li>\n<li><strong>Zustände (Composite States mit Sub-State-Symbol <code>oo</code>)</strong>:</li>\n<li><code>STARTUP</code></li>\n<li><code>RUN</code></li>\n<li><code>SHUTDOWN</code></li>\n<li><code>SLEEP</code></li>\n<li><code>WAKEUP</code></li>\n<li><strong>Ereignisse / Guards / Aktionen an Übergängen</strong>:</li>\n<li>Ereignisse: <code>Power on</code>, <code>Normal startup</code>, <code>Wakeup by wakeup source with integrated power control</code>, <code>All applications have shut down</code>, <code>Wakeup event</code>, <code>Reset</code>, <code>Power off</code>, <code>other</code>.</li>\n<li>Guard / Action: <code>[SLEEP == true ? /TTII]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Start</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beginn im Pseudozustand <code>OFF</code> über Übergang <code>Power on</code> nach <code>STARTUP</code>.</li>\n<li>Von <code>STARTUP</code> regulärer Wechsel nach <code>RUN</code> über <code>Normal startup</code>.</li>\n<li>Alternativ von <code>STARTUP</code> direkter Wechsel nach <code>WAKEUP</code> über <code>Wakeup by wakeup source with integrated power control</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb und Herunterfahren</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>RUN</code> Übergang nach <code>SHUTDOWN</code>, sobald <code>All applications have shut down</code> eintritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi und Wakeup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> Wechsel nach <code>SLEEP</code> über Bedingung/Ereignis <code>other</code>.</li>\n<li>Bei Auftreten eines Wakeup-Ereignisses (<code>Wakeup event</code>) in <code>SLEEP</code> erfolgt der Übergang nach <code>WAKEUP</code>.</li>\n<li>Tritt bereits während <code>SHUTDOWN</code> ein <code>Wakeup event</code> auf, wird direkt nach <code>WAKEUP</code> gewechselt.</li>\n<li>Ein Übergang führt von <code>WAKEUP</code> zurück nach <code>SHUTDOWN</code> unter der Guard-/Aktionsbedingung <code>SLEEP == true ? /TTII</code>.</li>\n<li>Von <code>WAKEUP</code> führt der reguläre Rückweg über <code>other</code> zurück nach <code>RUN</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung / Neustart</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> über <code>Reset</code> zurück zu <code>STARTUP</code>.</li>\n<li>Von <code>SHUTDOWN</code> über <code>Power off</code> in den Endzustand <code>OFF</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Top-Level-Zustandsverhalten des EcuM (Fixed Architecture).</li>\n<li>Sämtliche Hauptzustände (<code>STARTUP</code>, <code>RUN</code>, <code>SHUTDOWN</code>, <code>SLEEP</code>, <code>WAKEUP</code>) sind hierarchische Verbundzustände mit unterlagerten Zustandsmaschinen.</li>\n<li>Implementierungen müssen sicherstellen, dass Wakeup-Ereignisse sowohl im Ruhezustand (<code>SLEEP</code>) als auch im Herunterfahrprozess (<code>SHUTDOWN</code>) priorisiert abgefangen werden.</li>\n<li>Der Guard <code>SLEEP == true ? /TTII</code> spezifiziert die Rückführung in den Shutdown-Ablauf, falls ein Schlafzustand bereits als Zielbedingung aktiv war bzw. TTII (Time Triggered / Timer Interrupt Handling) greift.</li>\n</ul>"}, {"id": "FIG-4e7c7c30959e6c56", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Darstellung der obersten Ebene des Lebenszyklus und der Betriebsmodi des AUTOSAR ECU State Manager (EcuM Fixed).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pseudozustände</strong>:</li>\n<li>Anfangszustand (ausgefüllter Kreis, beschriftet mit <code>OFF</code>).</li>\n<li>Endzustand (umrandeter Kreis mit Punkt, beschriftet mit <code>OFF</code>).</li>\n<li><strong>Zustände (Composite States mit Sub-State-Symbol <code>oo</code>)</strong>:</li>\n<li><code>STARTUP</code></li>\n<li><code>RUN</code></li>\n<li><code>SHUTDOWN</code></li>\n<li><code>SLEEP</code></li>\n<li><code>WAKEUP</code></li>\n<li><strong>Ereignisse / Guards / Aktionen an Übergängen</strong>:</li>\n<li>Ereignisse: <code>Power on</code>, <code>Normal startup</code>, <code>Wakeup by wakeup source with integrated power control</code>, <code>All applications have shut down</code>, <code>Wakeup event</code>, <code>Reset</code>, <code>Power off</code>, <code>other</code>.</li>\n<li>Guard / Action: <code>[SLEEP == true ? /TTII]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Start</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beginn im Pseudozustand <code>OFF</code> über Übergang <code>Power on</code> nach <code>STARTUP</code>.</li>\n<li>Von <code>STARTUP</code> regulärer Wechsel nach <code>RUN</code> über <code>Normal startup</code>.</li>\n<li>Alternativ von <code>STARTUP</code> direkter Wechsel nach <code>WAKEUP</code> über <code>Wakeup by wakeup source with integrated power control</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb und Herunterfahren</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>RUN</code> Übergang nach <code>SHUTDOWN</code>, sobald <code>All applications have shut down</code> eintritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi und Wakeup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> Wechsel nach <code>SLEEP</code> über Bedingung/Ereignis <code>other</code>.</li>\n<li>Bei Auftreten eines Wakeup-Ereignisses (<code>Wakeup event</code>) in <code>SLEEP</code> erfolgt der Übergang nach <code>WAKEUP</code>.</li>\n<li>Tritt bereits während <code>SHUTDOWN</code> ein <code>Wakeup event</code> auf, wird direkt nach <code>WAKEUP</code> gewechselt.</li>\n<li>Ein Übergang führt von <code>WAKEUP</code> zurück nach <code>SHUTDOWN</code> unter der Guard-/Aktionsbedingung <code>SLEEP == true ? /TTII</code>.</li>\n<li>Von <code>WAKEUP</code> führt der reguläre Rückweg über <code>other</code> zurück nach <code>RUN</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung / Neustart</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> über <code>Reset</code> zurück zu <code>STARTUP</code>.</li>\n<li>Von <code>SHUTDOWN</code> über <code>Power off</code> in den Endzustand <code>OFF</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Top-Level-Zustandsverhalten des EcuM (Fixed Architecture).</li>\n<li>Sämtliche Hauptzustände (<code>STARTUP</code>, <code>RUN</code>, <code>SHUTDOWN</code>, <code>SLEEP</code>, <code>WAKEUP</code>) sind hierarchische Verbundzustände mit unterlagerten Zustandsmaschinen.</li>\n<li>Implementierungen müssen sicherstellen, dass Wakeup-Ereignisse sowohl im Ruhezustand (<code>SLEEP</code>) als auch im Herunterfahrprozess (<code>SHUTDOWN</code>) priorisiert abgefangen werden.</li>\n<li>Der Guard <code>SLEEP == true ? /TTII</code> spezifiziert die Rückführung in den Shutdown-Ablauf, falls ein Schlafzustand bereits als Zielbedingung aktiv war bzw. TTII (Time Triggered / Timer Interrupt Handling) greift.</li>\n</ul>"}, {"id": "FIG-c8dacd112e16d992", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Darstellung der obersten Ebene des Lebenszyklus und der Betriebsmodi des AUTOSAR ECU State Manager (EcuM Fixed).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pseudozustände</strong>:</li>\n<li>Anfangszustand (ausgefüllter Kreis, beschriftet mit <code>OFF</code>).</li>\n<li>Endzustand (umrandeter Kreis mit Punkt, beschriftet mit <code>OFF</code>).</li>\n<li><strong>Zustände (Composite States mit Sub-State-Symbol <code>oo</code>)</strong>:</li>\n<li><code>STARTUP</code></li>\n<li><code>RUN</code></li>\n<li><code>SHUTDOWN</code></li>\n<li><code>SLEEP</code></li>\n<li><code>WAKEUP</code></li>\n<li><strong>Ereignisse / Guards / Aktionen an Übergängen</strong>:</li>\n<li>Ereignisse: <code>Power on</code>, <code>Normal startup</code>, <code>Wakeup by wakeup source with integrated power control</code>, <code>All applications have shut down</code>, <code>Wakeup event</code>, <code>Reset</code>, <code>Power off</code>, <code>other</code>.</li>\n<li>Guard / Action: <code>[SLEEP == true ? /TTII]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Start</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beginn im Pseudozustand <code>OFF</code> über Übergang <code>Power on</code> nach <code>STARTUP</code>.</li>\n<li>Von <code>STARTUP</code> regulärer Wechsel nach <code>RUN</code> über <code>Normal startup</code>.</li>\n<li>Alternativ von <code>STARTUP</code> direkter Wechsel nach <code>WAKEUP</code> über <code>Wakeup by wakeup source with integrated power control</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb und Herunterfahren</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>RUN</code> Übergang nach <code>SHUTDOWN</code>, sobald <code>All applications have shut down</code> eintritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi und Wakeup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> Wechsel nach <code>SLEEP</code> über Bedingung/Ereignis <code>other</code>.</li>\n<li>Bei Auftreten eines Wakeup-Ereignisses (<code>Wakeup event</code>) in <code>SLEEP</code> erfolgt der Übergang nach <code>WAKEUP</code>.</li>\n<li>Tritt bereits während <code>SHUTDOWN</code> ein <code>Wakeup event</code> auf, wird direkt nach <code>WAKEUP</code> gewechselt.</li>\n<li>Ein Übergang führt von <code>WAKEUP</code> zurück nach <code>SHUTDOWN</code> unter der Guard-/Aktionsbedingung <code>SLEEP == true ? /TTII</code>.</li>\n<li>Von <code>WAKEUP</code> führt der reguläre Rückweg über <code>other</code> zurück nach <code>RUN</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung / Neustart</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>SHUTDOWN</code> über <code>Reset</code> zurück zu <code>STARTUP</code>.</li>\n<li>Von <code>SHUTDOWN</code> über <code>Power off</code> in den Endzustand <code>OFF</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Top-Level-Zustandsverhalten des EcuM (Fixed Architecture).</li>\n<li>Sämtliche Hauptzustände (<code>STARTUP</code>, <code>RUN</code>, <code>SHUTDOWN</code>, <code>SLEEP</code>, <code>WAKEUP</code>) sind hierarchische Verbundzustände mit unterlagerten Zustandsmaschinen.</li>\n<li>Implementierungen müssen sicherstellen, dass Wakeup-Ereignisse sowohl im Ruhezustand (<code>SLEEP</code>) als auch im Herunterfahrprozess (<code>SHUTDOWN</code>) priorisiert abgefangen werden.</li>\n<li>Der Guard <code>SLEEP == true ? /TTII</code> spezifiziert die Rückführung in den Shutdown-Ablauf, falls ein Schlafzustand bereits als Zielbedingung aktiv war bzw. TTII (Time Triggered / Timer Interrupt Handling) greift.</li>\n</ul>"}], "trans": [{"from": "FIG-9e4a0da848bad065", "to": "FIG-2ab6e57d2b5bee8c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>UML-Diagrammrahmen mit Kopfzeile <code>stm EcuM Main State Machine</code> sowie die obere und äußere Umrandung entfernt.</li>\n</ul>"}, {"from": "FIG-2ab6e57d2b5bee8c", "to": "FIG-4e7c7c30959e6c56", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4e7c7c30959e6c56", "to": "FIG-c8dacd112e16d992", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
